<?php require 'includes/bootstrap.php';if($_SERVER['REQUEST_METHOD']==='POST'){ $s=$pdo->prepare('SELECT * FROM students WHERE email=?');$s->execute([trim($_POST['email'])]);$u=$s->fetch();if($u&&password_verify($_POST['password'],$u['password_hash'])){session_regenerate_id(true);$_SESSION['student_id']=$u['student_id'];$_SESSION['student_name']=$u['name'];redirect('student/dashboard.php');}flash('error','Invalid email or password.');}$title='Student Login';$base='';$nav='<a href="register.php">Register</a>';include 'includes/header.php';?><div class="card form"><h2>Student Login</h2><form method="post"><label>Email</label><input type="email" name="email" required><label>Password</label><input type="password" name="password" required><div class="actions"><button class="btn">Login</button></div></form></div><?php include 'includes/footer.php';?>
